wb = Workbook()

def head(ws, n, row=1):
    for c in range(1, n + 1):
        x = ws.cell(row=row, column=c)
        x.fill = HDR_FILL; x.font = HDR_FONT
        x.alignment = Alignment(wrap_text=True, vertical="center", horizontal="center")
        x.border = BORDER
    ws.freeze_panes = ws.cell(row=row + 1, column=1)

def wid(ws, ws_widths):
    for i, w in enumerate(ws_widths, start=1):
        ws.column_dimensions[ws.cell(row=1, column=i).column_letter].width = w

def body(ws, n, start=2):
    for r in range(start, ws.max_row + 1):
        for c in range(1, n + 1):
            x = ws.cell(row=r, column=c)
            x.alignment = WRAP; x.border = BORDER

