# ЭКСПОРТ JSON
# ============================================================
data = dict(
    meta=dict(region=REGION, version="2.0",
              note="База формулировок. Источник правды — build_matrix.py"),
    payment_modules=PAY,
    payment_order=PAY_ORDER,
    scenarios=[dict(id=no, format=fmt, modules=codes) for no, fmt, codes in SIT],
    contract_matrix=MX,
    map_odkp=[dict(order=a, page=b, section=c, code=d, required=e) for a,b,c,d,e in MAP_ODKP],
    map_pdkp=[dict(order=a, section=b, content=c, code=d, note=e) for a,b,c,d,e in MAP_PDKP],
    fields=[dict(key=a, name=b, type=c, source=d, required=e, validation=f) for a,b,c,d,e,f in FIELDS],
    stop_factors=[dict(code=a, name=b, where=c, action=d) for a,b,c,d in STOPS],
    checklist=[dict(stage=a, block=b, document=c, source=d, purpose=e, status=f) for a,b,c,d,e,f in CHK],
    requisites=[dict(obj=a, value=b, usage=c) for a,b,c in REQS],
    rules=[dict(code=a, name=b, content=c) for a,b,c in RULES],
    groups=sorted({m["group"] for m in MX if m["group"] != "—"}),
)
with open(JSONF, "w", encoding="utf-8") as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

